using System.Globalization;
using CircuitRF.Core.Devices.Composed;
using CircuitRF.Core.Expressions;
using CircuitRF.Design.Modeling;
using Xunit;
using Xunit.Abstractions;

namespace CircuitRF.Ui.Tests.ModelComposer;

/// <summary>
/// brief-modelcomposer-7 §4: fitting the Angelov template to I–V generated by an Angelov drain current — written here
/// from the law's published form, not the template's text — recovers its parameters, from the template's own start
/// estimated from the data.
/// </summary>
public sealed class CurrentFitEquationTests(ITestOutputHelper output)
{
    private static readonly (string Name, double Value)[] Truth =
        [("Ipk", 0.05), ("Vpk", -0.6), ("P1", 1.8), ("P2", 0.25), ("P3", -0.12), ("Alpha", 2.2), ("Lambda", 0.04)];

    private static double Angelov(double vgs, double vds)
    {
        var p = Truth.ToDictionary(t => t.Name, t => t.Value);
        double x = vgs - p["Vpk"];
        double psi = p["P1"] * x + p["P2"] * x * x + p["P3"] * x * x * x;
        return p["Ipk"] * (1 + Math.Tanh(psi)) * (1 + p["Lambda"] * vds) * Math.Tanh(p["Alpha"] * vds);
    }

    [Fact]
    public void AngelovTemplate_RecoversItsParameters()
    {
        var points = new List<BiasPoint>();
        for (double vgs = -2.0; vgs <= 0.401; vgs += 0.2)
            foreach (double vds in (double[])[0, 0.2, 0.4, 0.6, 0.8, 1.2, 1.6, 2.4, 3.2, 4.8, 6.4, 8])
                points.Add(new BiasPoint(string.Create(CultureInfo.InvariantCulture, $"{vgs:F1}_{vds}"), vgs, vds, double.NaN, Angelov(vgs, vds)));
        var iv = new NormalisedData { Points = points };
        var set = new CmcDataSet
        {
            Name = "sim", Kind = DataSetKind.SimulatedTables, Sources = ["sim.npy"],
            Conditions = new DataConditions { ReferencePlane = ReferencePlane.Intrinsic },
            Import = new ImportSettings { Format = ImportSettings.Npy, Arrays = new Dictionary<string, string> { ["vgs"] = "vgs", ["vds"] = "vds", ["id"] = "id" } },
        };
        var doc = new CmcDocument { Kind = CmcKind.Active, DataSets = [set] };
        var ds = IntrinsicExtraction.Compute(set, iv, PadDeembedding.Load(PadsSettings.None, "."), null, null, null, []);
        var intrinsic = new IntrinsicResult(new Dictionary<string, RfCore.Data.DataSet> { ["sim"] = ds }, []);

        var settings = CurrentFitSettings.Default with
        {
            Id = new CurrentConstituentSettings { Method = CurrentMethod.Equation, Template = CurrentTemplates.Angelov },
        };
        var fit = CurrentFit.Run(doc, new Dictionary<string, NormalisedData> { ["sim"] = iv }, intrinsic, settings);
        foreach (string line in fit.Record.Report) output.WriteLine(line);

        var c = fit.Record.Id;
        Assert.Equal(Constituent.EquationMethod, c.Method);
        var got = c.Parameters.ToDictionary(kv => kv.Key, kv => kv.Value);
        foreach (var (name, value) in Truth)
        {
            output.WriteLine($"{name}: {got[name]:G8} (truth {value:G8})");
            Assert.True(Math.Abs(got[name] - value) <= 1e-3 * Math.Max(Math.Abs(value), 0.1), $"{name}: {got[name]:G8} vs {value}");
        }
        // The equation the record carries is the template's own text, so the exported model computes what was fitted.
        Assert.Equal(CurrentTemplates.Find(CurrentTemplates.Angelov)!.Id, c.Expression("Expression"));
        Assert.Contains("no gate current in the data; Ig is zero.", fit.Record.Report);
    }
}
